#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4
REPO_SLUG="asqatqazet/AI-Assisted-Review-Generation"
DEPLOY_ROLE_NAME="review-github-deploy-student"
POLICY_NAME="ReviewStudentServiceRoleManagement"
ROLE_URL="https://us-east-1.console.aws.amazon.com/iam/home#/roles/details/${DEPLOY_ROLE_NAME}?section=permissions"

banner "Repair student deployment IAM permissions"

stage "Validate repository and deployment identity"
say "This wizard reads one existing public GitHub variable. It never asks for AWS keys or secrets."
for command_name in git gh; do
  command -v "$command_name" >/dev/null 2>&1 || {
    warn "$command_name is required before continuing"
    exit 1
  }
done
gh auth status >/dev/null 2>&1 || {
  open_url "https://cli.github.com/manual/gh_auth_login"
  warn "Run: gh auth login"
  exit 1
}
CURRENT_REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
[[ "$CURRENT_REPO" == "$REPO_SLUG" ]] || {
  warn "Expected $REPO_SLUG, got $CURRENT_REPO"
  exit 1
}
AWS_DEPLOY_ROLE_ARN=$(gh variable get AWS_DEPLOY_ROLE_ARN --repo "$REPO_SLUG")
if [[ "$AWS_DEPLOY_ROLE_ARN" =~ ^arn:aws:iam::([0-9]{12}):role/review-github-deploy-student$ ]]; then
  AWS_ACCOUNT_ID="${BASH_REMATCH[1]}"
else
  warn "AWS_DEPLOY_ROLE_ARN is missing or does not name $DEPLOY_ROLE_NAME"
  exit 1
fi
say "Repository: $REPO_SLUG"
say "AWS account: $AWS_ACCOUNT_ID"
say "Deployment role: $DEPLOY_ROLE_NAME"
pause "Confirm these are the intended student deployment targets."

stage "Open the exact IAM role"
say "Sign in with an administrator identity. Do not paste a password, MFA code, or access key here."
open_url "$ROLE_URL"
step "After sign-in, verify the account ID is $AWS_ACCOUNT_ID."
step "Verify the page heading is $DEPLOY_ROLE_NAME and open its Permissions tab."
if ! confirm "Are you on the Permissions tab for $DEPLOY_ROLE_NAME in account $AWS_ACCOUNT_ID?"; then
  warn "No AWS change was made. Re-run after opening the correct account and role."
  exit 1
fi

stage "Install and verify the scoped inline policy"
POLICY_FILE=$(mktemp "${TMPDIR:-/tmp}/review-student-role-policy.XXXXXX")
trap 'rm -f "$POLICY_FILE"' EXIT
cat > "$POLICY_FILE" <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ManageStudentLambdaServiceRoles",
      "Effect": "Allow",
      "Action": [
        "iam:CreateRole",
        "iam:GetRole",
        "iam:DeleteRole",
        "iam:UpdateAssumeRolePolicy",
        "iam:TagRole",
        "iam:UntagRole",
        "iam:PutRolePolicy",
        "iam:GetRolePolicy",
        "iam:DeleteRolePolicy",
        "iam:ListRolePolicies",
        "iam:ListAttachedRolePolicies",
        "iam:ListInstanceProfilesForRole",
        "iam:ListRoleTags"
      ],
      "Resource": "arn:aws:iam::$AWS_ACCOUNT_ID:role/review-*-student-role"
    },
    {
      "Sid": "PassStudentRolesOnlyToLambda",
      "Effect": "Allow",
      "Action": "iam:PassRole",
      "Resource": "arn:aws:iam::$AWS_ACCOUNT_ID:role/review-*-student-role",
      "Condition": {
        "StringEquals": {
          "iam:PassedToService": "lambda.amazonaws.com"
        }
      }
    }
  ]
}
POLICY
if command -v pbcopy >/dev/null 2>&1; then
  pbcopy < "$POLICY_FILE"
  say "The policy JSON is on your clipboard."
elif command -v wl-copy >/dev/null 2>&1; then
  wl-copy < "$POLICY_FILE"
  say "The policy JSON is on your clipboard."
else
  say "Copy the policy JSON printed below:"
  printf '\n'
  sed 's/^/  /' "$POLICY_FILE"
  printf '\n'
fi
step "Choose Add permissions → Create inline policy."
step "Choose JSON, replace the editor contents with the copied policy, then choose Next."
step "Name the policy $POLICY_NAME. Review that its Resource ends role/review-*-student-role."
step "Choose Create policy. This is the only permission-changing action in the wizard."
pause "Create the inline policy, then press Enter."
open_url "$ROLE_URL"
step "Under Permissions policies, expand $POLICY_NAME and verify both statements are present."
if ! confirm "Is $POLICY_NAME now listed on $DEPLOY_ROLE_NAME?"; then
  warn "Deployment remains blocked until the inline policy is visible on the role."
  exit 1
fi

stage "Resume and monitor the low-quota deployment"
say "The failed Terraform run saved partial state. Re-running resumes safely from that state."
ask REVIEW_TEARDOWN_DATE "Enter the teardown date [2026-09-07]:"
[[ -n "$REVIEW_TEARDOWN_DATE" ]] || REVIEW_TEARDOWN_DATE="2026-09-07"
[[ "$REVIEW_TEARDOWN_DATE" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || {
  warn "The teardown date must use YYYY-MM-DD."
  exit 1
}
say "Deployment profile: student-low-quota"
say "Provider mode: FakeProvider only"
say "Teardown date: $REVIEW_TEARDOWN_DATE"
if ! confirm "Dispatch this deployment from main now?"; then
  SKIPPED+=("Deployment not dispatched; run deploy-student with student-low-quota later")
  finish
  exit 0
fi
RUN_URL=$(gh workflow run deploy-student.yml \
  --repo "$REPO_SLUG" \
  --ref main \
  -f "teardown_date=$REVIEW_TEARDOWN_DATE" \
  -f "deployment_profile=student-low-quota" \
  -f "acknowledge_fake_provider_only=true")
RUN_ID="${RUN_URL##*/}"
say "Deployment dispatched: $RUN_URL"
open_url "$RUN_URL"
if confirm "Monitor this GitHub Actions run in the terminal?"; then
  if gh run watch "$RUN_ID" --repo "$REPO_SLUG" --exit-status; then
    say "Deployment workflow completed successfully."
  else
    warn "Deployment failed. Keep the run URL and inspect its first failed step."
    SKIPPED+=("Deployment run $RUN_ID needs diagnosis: $RUN_URL")
  fi
fi

finish
